import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

export default function Checkout() {
  const initialCart = [
    {
      id: 1,
      name: "Ajwa Dates",
      basePrice: 300, // price for 250g
      image: "https://via.placeholder.com/80",
      quantity: 1,
      weight: "250g"
    },
    {
      id: 2,
      name: "Almonds",
      basePrice: 250,
      image: "https://via.placeholder.com/80",
      quantity: 1,
      weight: "250g"
    }
  ];

  const weightMultiplier = {
    "250g": 1,
    "500g": 2,
    "1kg": 4
  };

  const [cartItems, setCartItems] = useState(initialCart);

  const handleQuantityChange = (id, value) => {
    setCartItems(
      cartItems.map((item) =>
        item.id === id
          ? { ...item, quantity: Math.max(1, value) }
          : item
      )
    );
  };

  const handleWeightChange = (id, weight) => {
    setCartItems(
      cartItems.map((item) =>
        item.id === id ? { ...item, weight } : item
      )
    );
  };

  const getItemTotal = (item) =>
    item.basePrice *
    weightMultiplier[item.weight] *
    item.quantity;

  const subtotal = cartItems.reduce(
    (sum, item) => sum + getItemTotal(item),
    0
  );

  const shipping = 50;
  const total = subtotal + shipping;

  const handlePayNow = () => {
    alert("Redirecting to payment gateway...");
  };

  return (
    <div className="container my-5">
      <h2 className="text-center mb-4">Checkout</h2>

      <div className="row">
        {/* Order Details */}
        <div className="col-md-8">
          <div className="card shadow-sm">
            <div className="card-header bg-primary text-white">
              Ordered Products
            </div>

            <div className="card-body">
              {cartItems.map((item) => (
                <div
                  key={item.id}
                  className="row align-items-center border-bottom py-3"
                >
                  <div className="col-3 col-md-2">
                    <img
                      src={item.image}
                      alt={item.name}
                      className="img-fluid rounded"
                    />
                  </div>

                  <div className="col-9 col-md-4">
                    <h6>{item.name}</h6>
                    <small className="text-muted">
                      Selected Weight: <strong>{item.weight}</strong>
                    </small>
                  </div>

                  <div className="col-md-2 mt-2 mt-md-0">
                    <select
                      className="form-select"
                      value={item.weight}
                      onChange={(e) =>
                        handleWeightChange(item.id, e.target.value)
                      }
                    >
                      <option value="250g">250g</option>
                      <option value="500g">500g</option>
                      <option value="1kg">1kg</option>
                    </select>
                  </div>

                  <div className="col-md-2 mt-2 mt-md-0">
                    <input
                      type="number"
                      min="1"
                      className="form-control"
                      value={item.quantity}
                      onChange={(e) =>
                        handleQuantityChange(item.id, e.target.value)
                      }
                    />
                  </div>

                  <div className="col-md-2 text-end mt-2 mt-md-0">
                    <strong>₹{getItemTotal(item)}</strong>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Price Summary */}
        <div className="col-md-4 mt-4 mt-md-0">
          <div className="card shadow-sm">
            <div className="card-header bg-success text-white">
              Price Details
            </div>

            <div className="card-body">
              <div className="d-flex justify-content-between mb-2">
                <span>Subtotal</span>
                <span>₹{subtotal}</span>
              </div>

              <div className="d-flex justify-content-between mb-2">
                <span>Shipping</span>
                <span>₹{shipping}</span>
              </div>

              <hr />

              <div className="d-flex justify-content-between mb-3">
                <strong>Total</strong>
                <strong>₹{total}</strong>
              </div>

              <button
                className="btn btn-success w-100"
                onClick={handlePayNow}
              >
                Pay Now
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
